import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] delta = new long[n];
        for (int i = 0; i < n; i++) delta[i] = nextLong();
        for (int i = 0; i < n; i++) delta[i] -= nextLong();
        // Pair (i, j) is a win iff delta[i] + delta[j] > 0; order does not matter for counting.
        Arrays.sort(delta);
        int left = 0, right = n - 1;
        long answer = 0;
        while (left < right) {
            if (delta[left] + delta[right] > 0) {
                answer += right - left;
                right--;
            } else {
                left++;
            }
        }
        System.out.println(answer % 1000000007L);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	delta := make([]int64, n)
	for i := range delta {
		delta[i] = nextInt()
	}
	for i := range delta {
		delta[i] -= nextInt()
	}
	// Pair (i, j) is a win iff delta[i] + delta[j] > 0; order does not matter for counting.
	slices.Sort(delta)
	left, right := 0, n-1
	var answer int64
	for left < right {
		if delta[left]+delta[right] > 0 {
			answer += int64(right - left)
			right--
		} else {
			left++
		}
	}
	fmt.Println(answer % 1000000007)
}
